import { defineResource, field } from '@cossackframework/cms';

export const tickets = defineResource({
    name: 'tickets',
    label: 'Tickets',
    titleField: 'subject',
    ownership: true,
    fields: {
        subject: field.string({ required: true, max: 120, search: true }),
        status: field.enum(['open', 'closed'], { required: true, default: 'open', index: true }),
        priority: field.integer({ min: 1, max: 5, default: 3 }),
        assignee: field.string({ nullable: true }),
        team: field.string(),
    },
    access: {
        read: { any: ['owner', { permission: 'app/tickets:read' }] },
        create: 'authenticated',
        update: { any: ['owner', { permission: 'app/tickets:update' }] },
        delete: { permission: 'app/tickets:delete' },
    },
    // Generated changes are additive; stricter rules are explicit, ordered steps.
    migrations: [
        { version: 1, kind: 'backfill', field: 'team', value: 'support' },
    ],
});

import { createFastDB, MemoryPendingWriteStore } from '@cossackframework/fastdb';
import { contentModule, createCMS, isCmsError, userPrincipal } from '@cossackframework/cms/server';

const db = createFastDB({ url: 'http://127.0.0.1:4321', token: 'local-service-token', pending: new MemoryPendingWriteStore() });
const cms = createCMS({ db, modules: [contentModule] });
const editor = userPrincipal('user-1', ['editor'], ['cms/posts:*']);

export async function publish(): Promise<string> {
    const report = await cms.migrate();
    if (report.failed) return report.failed.message;
    const posts = cms.resource('cms/posts');
    // The slug is derived from the title: hello-world.
    const draft = await posts.create({ title: 'Hello world' }, { principal: editor });
    try {
        // One atomic batch: the record, its revision, the audit row and the outbox event.
        const live = await posts.update(draft.id, { status: 'published' }, { principal: editor, expectedRevision: draft.rev });
        return `${live.id} is at revision ${live.rev}`;
    } catch (error) {
        if (isCmsError(error, 'CMS_CONFLICT')) return 'Someone else changed the post.';
        throw error;
    } finally {
        await cms.outbox.dispatch();
    }
}

import { createFastDB, MemoryPendingWriteStore } from '@cossackframework/fastdb';
import { contentModule, createCMS, field, userPrincipal } from '@cossackframework/cms/server';

const db = createFastDB({ url: 'http://127.0.0.1:4321', token: 'local-service-token', pending: new MemoryPendingWriteStore() });
const cms = createCMS({ db, modules: [contentModule] });
const admin = userPrincipal('admin-1', ['admin'], ['*']);

export async function launchShop(): Promise<string> {
    await cms.migrate();
    await cms.saveTaxonomy({ name: 'brands', label: 'Brands', singular: 'Brand', hierarchical: false, path: 'brand' }, admin);
    await cms.saveCollection({
        name: 'products', label: 'Products', singular: 'Product', path: 'shop', taxonomies: ['brands'],
        fields: {
            price: field.number({ required: true, min: 0, label: 'Price' }),
            content: field.blocks({ blocks: ['core/heading', 'core/paragraph', 'core/image'], label: 'Content' }),
        },
    }, admin);
    const [acme] = await cms.taxonomies.ensure('brands', ['Acme'], { principal: admin });
    const product = await cms.resource('cms/products').create({
        title: 'Rocket skates', price: 19.5, brands: [acme!], status: 'published',
        content: [{ id: 'intro', type: 'core/heading', data: { text: 'Fast wheels' } }],
    }, { principal: admin });
    await cms.settings.update('reading', { postsPerPage: 12 }, { principal: admin });
    return `/shop/${String(product.slug)}`;
}

import { createFastDB, MemoryPendingWriteStore } from '@cossackframework/fastdb';
import { contentModule, createCMS, richTextExcerpt, richTextHtml, userPrincipal, type MenuItem, type RichTextDoc } from '@cossackframework/cms/server';

const db = createFastDB({ url: 'http://127.0.0.1:4321', token: 'local-service-token', pending: new MemoryPendingWriteStore() });
const cms = createCMS({ db, modules: [contentModule] });
const admin = userPrincipal('admin-1', ['admin'], ['*']);

export async function publishWithMenu(): Promise<{ html: string; excerpt: string; menu: string[] }> {
    const body: RichTextDoc = { type: 'doc', content: [
        { type: 'heading', attrs: { level: 2 }, content: [{ type: 'text', text: 'Opening hours' }] },
        { type: 'paragraph', content: [{ type: 'text', text: 'Open ' }, { type: 'text', text: 'every day', marks: [{ type: 'bold' }] }] },
    ] };
    const about = await cms.resource('cms/pages').create({ title: 'About', body, status: 'published' }, { principal: admin });
    const items: MenuItem[] = [
        { id: 'about', kind: 'entry', label: '', collection: 'pages', entry: about.id, children: [] },
        { id: 'blog', kind: 'archive', label: 'Blog', collection: 'posts', children: [] },
    ];
    const menu = await cms.menus.create({ name: 'Main', items }, { principal: admin });
    const locations = (await cms.menuLocations()).map(location => location.name);
    if (locations.includes('primary')) await cms.menus.place(menu.id, ['primary'], { principal: admin, known: locations });
    const resolved = await cms.menus.forLocation('primary') ?? [];
    return { html: richTextHtml(about.body as RichTextDoc), excerpt: richTextExcerpt(about.body as RichTextDoc, 20), menu: resolved.map(item => item.url) };
}

import { afterCommit, beforeWrite } from '@cossackframework/cms';
import type { PluginContext } from '@cossackframework/cms/server';

/** src/plugins/support-desk/server.ts: called once by the CMS host at boot. */
export function register(context: PluginContext): void {
    context.hooks.addFilter(beforeWrite, (draft, { input }) =>
        input.resource === 'support-desk/tickets' && typeof draft.subject === 'string' ? { ...draft, subject: draft.subject.trim() } : draft);
    context.hooks.addAction(afterCommit, async event => {
        // Deliveries can repeat: event.eventId is the idempotency key.
        await context.fetch(`https://hooks.example.com/tickets/${event.id}`, { method: 'POST', headers: { 'idempotency-key': event.eventId } });
    });
    context.commands.add('close-all', async (_input, { principal }) => {
        const tickets = context.cms.resource('support-desk/tickets');
        const page = await tickets.list({ where: { status: 'open' }, limit: 100 }, { principal });
        for (const ticket of page.records) await tickets.update(ticket.id, { status: 'closed' }, { principal, expectedRevision: ticket.rev });
        return page.records.length;
    });
}

import { Hono } from 'hono';
import { createFastDB, MemoryPendingWriteStore } from '@cossackframework/fastdb';
import { createCMS, createCmsAuth } from '@cossackframework/cms/server';

const db = createFastDB({ url: 'http://127.0.0.1:4321', token: 'local-service-token', pending: new MemoryPendingWriteStore() });
const cms = createCMS({ db });
const kit = createCmsAuth(cms, { secure: false });

export const app = new Hono();
app.use('*', kit.auth.middleware);
app.post('/sign-in', async c => {
    const form = await c.req.formData();
    const signedIn = await kit.signIn(String(form.get('email')), String(form.get('password')), c);
    if (!signedIn) return c.text('Wrong email or password.', 401);
    signedIn.headers.forEach((value, name) => c.header(name, value, { append: true }));
    return c.redirect('/');
});
app.get('/me', c => c.json(kit.principal(c)));
// The framework session bag, job and notification ledgers on FastDB:
export const stores = { sessions: cms.sessions, jobs: cms.jobs(), notifications: cms.notifications() };

import { createFastDB, MemoryPendingWriteStore } from '@cossackframework/fastdb';
import { contentModule, createCMS, userPrincipal } from '@cossackframework/cms/server';

const db = createFastDB({ url: 'http://127.0.0.1:4321', token: 'local-service-token', pending: new MemoryPendingWriteStore() });
const cms = createCMS({ db, modules: [contentModule] });
const editor = userPrincipal('editor-1', ['editor'], ['cms:dashboard', 'cms/*']);

export async function launchTomorrow(): Promise<string> {
    const tomorrow = Date.now() + 24 * 60 * 60 * 1000;
    const post = await cms.resource('cms/posts').create({ title: 'Launch day', status: 'published', publishedAt: tomorrow }, { principal: editor });
    // post.status is 'scheduled'; maintenance publishes it tomorrow.
    const link = await cms.createPreviewLink('cms/posts', post.id, editor);
    await cms.webhooks.save({ name: 'Rebuild', url: 'https://api.example.com/hooks/build', events: ['entry.published'], collections: ['posts'] });
    return `/preview/posts/${post.id}?token=${link.token}`;
}

export async function maintenance(): Promise<void> {
    await cms.publishDue();
    await cms.outbox.dispatch();
    await cms.webhooks.dispatch();
}
